{
  "findings": [
    {
      "check_id": "CKV_AWS_40",
      "title": "IAM policy attachment to user",
      "resource": "aws_iam_user_policy_attachment.privesc19-UpdateExistingGlueDevEndpoint-user-attach-policy",
      "severity": "HIGH",
      "explanation": "Attaching policies directly to IAM users is not recommended as it makes it harder to manage permissions at scale and increases the risk of privilege escalation. Instead, policies should be attached to groups or roles."
    }
  ],
  "patched_code": "resource \"aws_iam_group\" \"privesc19-UpdateExistingGlueDevEndpoint-group\" {\n  name = \"privesc19-UpdateExistingGlueDevEndpoint-group\"\n}\n\nresource \"aws_iam_user_group_membership\" \"privesc19-UpdateExistingGlueDevEndpoint-user-group-membership\" {\n  user = aws_iam_user.privesc19-UpdateExistingGlueDevEndpoint-user.name\n  groups = [aws_iam_group.privesc19-UpdateExistingGlueDevEndpoint-group.name]\n}\n\nresource \"aws_iam_group_policy_attachment\" \"privesc19-UpdateExistingGlueDevEndpoint-group-attach-policy\" {\n  group      = aws_iam_group.privesc19-UpdateExistingGlueDevEndpoint-group.name\n  policy_arn = aws_iam_policy.privesc19-UpdateExistingGlueDevEndpoint.arn\n}",
  "fix_summary": "Replaced the direct IAM user policy attachment with a group-based approach. Created an IAM group, added the user to the group, and attached the policy to the group instead."
}
